label("$B$",(3.4,2),NE);
label("$C$",(3.4,0),SE);
label("$D$",(0,0),SW);
label("$P$",(1.3,2),N);
</asy>

<math>\textbf{(A)}\ 3+\frac{\sqrt{3}}{3} \qquad\textbf{(B)}\ 2+\frac{4\sqrt{3}}{3} \qquad\textbf{(C)}\ 2+2\sqrt{2} \qquad\textbf{(D)}\ \frac{3+3\sqrt{5}}{2} \qquad\textbf{(E)}\ 2+\frac{5\sqrt{3}}{3}</math>

